def solve():
	(n, x, y) = [int(i) for i in input().split()]
	(a, b) = (input(), input())
	q = 0
	w = []
	for i in range(n):
		if a[i] != b[i]:
			q += 1
			w.append(i)
	if q % 2 != 0:
		return -1
	if q == 0:
		return 0
	if q != 2 or w[0] + 1 != w[1]:
		return q // 2 * y
	return min(y * 2, x)
t = int(input())
ans = []
while t:
	ans.append(str(solve()))
	t -= 1
print('\n'.join(ans))
